import { WebSocket, type WebSocketServer } from 'ws';

/**
 * Internal ws endpoint on the API server; live update server instances connect to it and every published event is sent to all connected instances.
 *
 * @trace DSN-034 REQ-003 REQ-007 REQ-011
 */
export class EventFeed {
  constructor(private readonly server: WebSocketServer) {}

  /**
   * Publishes an event on a topic to every connected live update instance.
   * Invalid input is rejected before anything is sent.
   */
  publish(topic: string, payload: string): void {
    if (typeof topic !== 'string' || topic.trim().length === 0) {
      throw new Error('Event topic must be a non-empty string');
    }
    if (typeof payload !== 'string') {
      throw new Error('Event payload must be a string');
    }
    const frame = JSON.stringify({ topic, payload });
    for (const client of this.server.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send(frame);
      }
    }
  }
}

import { WebSocket } from 'ws';
import { LiveGateway } from './LiveGateway.js';

/**
 * Live server side of the internal ws event feed; each live instance connects to the API server and so receives every event.
 * @trace DSN-032 REQ-003 REQ-007 REQ-011
 */
export class EventSubscriber {
  private socket: WebSocket | null = null;

  constructor(private readonly liveGateway: LiveGateway) {
    this.connect();
  }

  onEvent(topic: string, payload: string): void {
    if (typeof topic !== 'string' || topic.trim() === '') {
      throw new Error('Event topic must be a non-empty string');
    }
    if (typeof payload !== 'string') {
      throw new Error('Event payload must be a string');
    }
    let itemId = '';
    try {
      const parsed = JSON.parse(payload) as { itemId?: unknown };
      if (typeof parsed.itemId === 'string') {
        itemId = parsed.itemId;
      }
    } catch {
      // payload is not JSON; fall back to the topic
    }
    if (itemId === '') {
      const match = /^(?:item:|auction\.closed\.)(.+)$/.exec(topic);
      itemId = match ? match[1] : '';
    }
    if (itemId === '') {
      return;
    }
    this.liveGateway.broadcast(itemId, payload);
  }

  private connect(): void {
    const url = process.env.FEED_URL ?? 'ws://localhost:8080/internal/feed';
    const socket = new WebSocket(url);
    this.socket = socket;
    socket.on('message', (data) => {
      try {
        const frame = JSON.parse(String(data)) as { topic?: unknown; payload?: unknown };
        if (typeof frame.topic === 'string' && typeof frame.payload === 'string') {
          this.onEvent(frame.topic, frame.payload);
        }
      } catch (err) {
        console.error('Bad event from feed', err);
      }
    });
    socket.on('error', () => {
      // the close handler reconnects
    });
    socket.on('close', () => {
      if (this.socket !== socket) {
        return;
      }
      const timer = setTimeout(() => this.connect(), 1000);
      timer.unref();
    });
  }
}

import { createServer } from 'node:http';
import { randomUUID } from 'node:crypto';
import { WebSocket, WebSocketServer } from 'ws';

/**
 * WebSocket gateway for browsers; keeps watchers per item and broadcasts only to them.
 *
 * @trace DSN-033 REQ-003 REQ-009 REQ-011 REQ-004
 */
export class LiveGateway {
  private sockets: Map<string, WebSocket> = new Map();

  constructor(public watchers: Map<string, Set<string>>) {}

  /**
   * Creates a gateway that serves browsers with ws on /live at the given port.
   */
  static serve(port: number): LiveGateway {
    const gateway = new LiveGateway(new Map());
    const server = createServer();
    const wss = new WebSocketServer({ server, path: '/live' });
    wss.on('connection', (ws) => {
      const clientId = randomUUID();
      gateway.sockets.set(clientId, ws);
      ws.on('message', (data) => {
        try {
          const msg = JSON.parse(String(data)) as { action?: unknown; itemId?: unknown };
          const itemId = String(msg.itemId ?? '');
          if (msg.action === 'watch') {
            gateway.watch(clientId, itemId);
          } else if (msg.action === 'unwatch') {
            gateway.unwatch(clientId, itemId);
          } else {
            throw new Error('Unknown action');
          }
        } catch (err) {
          ws.send(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }));
        }
      });
      ws.on('error', () => {
        // close follows
      });
      ws.on('close', () => gateway.drop(clientId));
    });
    server.listen(port);
    return gateway;
  }

  watch(clientId: string, itemId: string): void {
    if (!clientId || !itemId) {
      throw new Error('clientId and itemId are required');
    }
    let clients = this.watchers.get(itemId);
    if (!clients) {
      clients = new Set<string>();
      this.watchers.set(itemId, clients);
    }
    if (clients.size >= 200 && !clients.has(clientId)) {
      throw new Error(`Item ${itemId} already has 200 watchers`);
    }
    clients.add(clientId);
  }

  unwatch(clientId: string, itemId: string): void {
    const clients = this.watchers.get(itemId);
    if (!clients) {
      return;
    }
    clients.delete(clientId);
    if (clients.size === 0) {
      this.watchers.delete(itemId);
    }
  }

  broadcast(itemId: string, message: string): void {
    if (!itemId) {
      throw new Error('itemId is required');
    }
    const clients = this.watchers.get(itemId);
    if (!clients) {
      return;
    }
    for (const clientId of clients) {
      const socket = this.sockets.get(clientId);
      if (socket && socket.readyState === WebSocket.OPEN) {
        socket.send(message);
      }
    }
  }

  private drop(clientId: string): void {
    this.sockets.delete(clientId);
    for (const itemId of [...this.watchers.keys()]) {
      this.unwatch(clientId, itemId);
    }
  }
}

import { randomUUID } from 'node:crypto';
import { DatabaseSync } from 'node:sqlite';
import { User } from './User.js';

/**
 * Persistence of users with unique display name, in the API server's SQLite database.
 *
 * @trace DSN-028 REQ-008
 */
export class UserStore {
  constructor(private readonly db: DatabaseSync) {
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS users (
        id TEXT PRIMARY KEY,
        display_name TEXT NOT NULL UNIQUE
      )
    `);
  }

  /**
   * Finds the user holding the given display name, or null when none does.
   */
  async findByName(displayName: string): Promise<User | null> {
    const rows = this.db
      .prepare('SELECT id, display_name FROM users WHERE display_name = ?')
      .all(displayName) as unknown as { id: string; display_name: string }[];
    return rows.length > 0 ? new User(rows[0].id, rows[0].display_name) : null;
  }

  /**
   * Stores a user. A display name must be 2 to 20 characters and may be held
   * by only one user id. Assigns a server-side id when none is given.
   */
  async save(user: User): Promise<User> {
    const name = user.displayName;
    if (typeof name !== 'string' || name.length < 2 || name.length > 20) {
      throw new Error('Display name must be between 2 and 20 characters');
    }

    const holder = await this.findByName(name);
    if (holder !== null && holder.id !== user.id) {
      throw new Error(`Display name ${name} is already taken`);
    }

    const id = user.id ? user.id : randomUUID();
    const existing = this.db
      .prepare('SELECT display_name FROM users WHERE id = ?')
      .all(id) as unknown as { display_name: string }[];
    if (existing.length > 0 && existing[0].display_name !== name) {
      throw new Error(`User ${id} already has a different display name`);
    }

    this.db
      .prepare('INSERT INTO users (id, display_name) VALUES (?, ?) ON CONFLICT(id) DO NOTHING')
      .run(id, name);
    return new User(id, name);
  }
}

import { randomUUID } from 'node:crypto';
import { Item } from './Item.js';
import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';
import { UserStore } from './UserStore.js';
import { ItemStore } from './ItemStore.js';
import { AuctionEventPublisher } from './AuctionEventPublisher.js';

/**
 * Creates and reads items, closes due auctions.
 * @trace DSN-022 REQ-001 REQ-004
 */
export class ItemService {
  constructor(private readonly itemStore: ItemStore, private readonly userStore: UserStore, private readonly auctionEventPublisher: AuctionEventPublisher) {}

  async listItem(sellerId: string, title: string, startingPrice: number, endTime: Date, currency: string): Promise<Item> {
    if (!sellerId || sellerId.trim() === '') {
      throw new Error('Seller id is required');
    }
    if (!title || title.trim() === '') {
      throw new Error('Title is required');
    }
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice) || startingPrice < 0) {
      throw new Error('Starting price is required and must be a non-negative number');
    }
    if (!(endTime instanceof Date) || Number.isNaN(endTime.getTime())) {
      throw new Error('End time is required');
    }
    if (endTime.getTime() <= Date.now()) {
      throw new Error('End time must be in the future');
    }
    const allowed = Object.values(Currency) as string[];
    if (!currency || !allowed.includes(currency)) {
      throw new Error('Currency must be one of CHF, EUR or USD');
    }
    const item = new Item(
      randomUUID(),
      sellerId,
      title,
      startingPrice,
      currency as Currency,
      endTime,
      AuctionStatus.open,
      null,
      null,
      null,
    );
    return this.itemStore.saveItem(item);
  }

  async getItem(id: string): Promise<Item> {
    const item = await this.itemStore.findItem(id);
    if (!item) {
      throw new Error(`Item ${id} not found`);
    }
    return item;
  }

  async listOpenItems(): Promise<Item[]> {
    return this.itemStore.findOpenItems();
  }

  async closeDueAuctions(now: Date): Promise<void> {
    const dueItems = await this.itemStore.findDueItems(now);
    for (const item of dueItems) {
      if (item.extendIfLate(now)) {
        await this.itemStore.saveItem(item);
        continue;
      }
      item.winnerId = item.highestBidderId;
      item.status = item.highestBidderId === null ? AuctionStatus.unsold : AuctionStatus.closed;
      await this.itemStore.saveItem(item);
      await this.auctionEventPublisher.publishAuctionClosed(item);
    }
  }
}

import express, { type Express, type NextFunction, type Request, type Response } from 'express';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import type { Server } from 'node:http';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { WebSocketServer } from 'ws';
import { UserStore } from '../auction-api/UserStore.js';
import { ItemStore } from '../auction-api/ItemStore.js';
import { UserService } from '../auction-api/UserService.js';
import { UserController } from '../auction-api/UserController.js';
import { EventFeed } from '../auction-api/EventFeed.js';
import { AuctionEventPublisher } from '../auction-api/AuctionEventPublisher.js';
import { BidEventPublisher } from '../auction-api/BidEventPublisher.js';
import { ItemService } from '../auction-api/ItemService.js';
import { ItemController } from '../auction-api/ItemController.js';
import { BidService } from '../auction-api/BidService.js';
import { BidController } from '../auction-api/BidController.js';
import { AuctionCloser } from '../auction-api/AuctionCloser.js';
import { FrankfurterClient } from '../exchange-rates/FrankfurterClient.js';
import { ExchangeRateService } from '../exchange-rates/ExchangeRateService.js';
import { Currency } from '../auction-api/Currency.js';
import type { FrankfurterApi } from '../frankfurter-service/FrankfurterApi.js';

const frankfurterApi: FrankfurterApi = {
  async latest(base: string): Promise<Record<string, number>> {
    const res = await fetch(`https://api.frankfurter.app/latest?from=${encodeURIComponent(base)}`);
    if (!res.ok) {
      throw new Error(`Frankfurter answered ${res.status}`);
    }
    const body = (await res.json()) as { rates?: Record<string, number> };
    return body.rates ?? {};
  },
};

export interface AppParts {
  app: Express;
  auctionCloser: AuctionCloser;
  feedServer: WebSocketServer;
}

function openDatabase(): DatabaseSync {
  const dbPath = process.env.DB_PATH ?? './data/auction.db';
  if (dbPath !== ':memory:') {
    mkdirSync(path.dirname(path.resolve(dbPath)), { recursive: true });
  }
  return new DatabaseSync(dbPath);
}

/** Routes ws upgrades on /internal/feed of the given http server to the feed. */
export function attachFeed(server: Server, feedServer: WebSocketServer): void {
  server.on('upgrade', (req, socket, head) => {
    const pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
    if (pathname === '/internal/feed') {
      feedServer.handleUpgrade(req, socket, head, (ws) => feedServer.emit('connection', ws, req));
    } else {
      socket.destroy();
    }
  });
}

export function createAppParts(): AppParts {
  const db = openDatabase();
  const userStore = new UserStore(db);
  const itemStore = new ItemStore(db);
  const userService = new UserService(userStore);
  const userController = new UserController(userService);
  const feedServer = new WebSocketServer({ noServer: true });
  const eventFeed = new EventFeed(feedServer);
  const auctionEventPublisher = new AuctionEventPublisher(eventFeed);
  const bidEventPublisher = new BidEventPublisher(eventFeed);
  const itemService = new ItemService(itemStore, userStore, auctionEventPublisher);
  const itemController = new ItemController(itemService);
  const bidService = new BidService(itemStore, bidEventPublisher, userStore);
  const bidController = new BidController(bidService);
  const auctionCloser = new AuctionCloser(itemService, 1000);
  const frankfurterClient = new FrankfurterClient(frankfurterApi);
  const exchangeRateService = new ExchangeRateService(frankfurterClient, 60 * 60 * 1000);

  const app = express();
  app.get('/health', (_req, res) => {
    res.status(200).json({ status: 'ok' });
  });
  app.use(express.json());
  app.use(express.static(fileURLToPath(new URL('../../public', import.meta.url))));

  app.post('/api/users', async (req, res) => {
    const body = req.body ?? {};
    res.status(201).json(await userController.register(body.displayName));
  });

  app.post('/api/items', async (req, res) => {
    const b = req.body ?? {};
    res.status(201).json(
      await itemController.listItem(b.userId, b.title, b.startingPrice, b.endTime, b.currency),
    );
  });

  app.get('/api/items', async (_req, res) => {
    res.json(await itemController.listOpenItems());
  });

  app.get('/api/items/:id', async (req, res) => {
    const dc = typeof req.query.displayCurrency === 'string' && req.query.displayCurrency !== ''
      ? req.query.displayCurrency
      : undefined;
    const view = await itemController.getItem(String(req.params.id), dc);
    if (view.displayCurrency !== null) {
      const to: Currency = view.displayCurrency;
      const item = view.item;
      view.convertedStartingPrice = await exchangeRateService.convert(item.startingPrice, item.currency, to);
      view.convertedHighestBid = item.highestBidAmount === null
        ? null
        : await exchangeRateService.convert(item.highestBidAmount, item.currency, to);
    }
    res.json(view);
  });

  app.post('/api/items/:id/bids', async (req, res) => {
    const b = req.body ?? {};
    res.status(201).json(await bidController.placeBid(String(req.params.id), b.userId, b.amount));
  });

  app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
    const message = err instanceof Error ? err.message : String(err);
    const status = err instanceof Error && message.endsWith('not found') ? 404 : 400;
    res.status(status).json({ error: message });
  });

  return { app, auctionCloser, feedServer };
}

export function createApp(): Express {
  return createAppParts().app;
}

import { attachFeed, createAppParts } from './app.js';

const { app, auctionCloser, feedServer } = createAppParts();
setInterval(() => {
  auctionCloser.tick().catch((err: unknown) => console.error(err));
}, auctionCloser.intervalMs);

const port = Number(process.env.PORT ?? 8080);
const server = app.listen(port, () => {
  console.log(`API server listening on port ${port}`);
});
attachFeed(server, feedServer);

